import SwiftUI

public struct TrainCardView: View {
    public let card: TrainCard
    public let onAction: ((String) -> Void)?

    public init(card: TrainCard, onAction: ((String) -> Void)? = nil) {
        self.card = card
        self.onAction = onAction
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 20) {
            // Header: SBB tile (36 in service red), Train line pill, Platform, Delay
            HStack(spacing: 8) {
                // SBB Tile in service red
                HStack(spacing: 6) {
                    Image(systemName: "tram.fill")
                        .font(.system(size: 17, weight: .bold))
                    Text("SBB")
                        .font(Theme.Typography.badge)
                }
                .foregroundColor(.white)
                .padding(.horizontal, 12)
                .frame(height: 36)
                .background {
                    RoundedRectangle(cornerRadius: 10, style: .continuous)
                        .fill(Theme.Colors.serviceSBB)
                }

                // Train Line
                GlassPillView(
                    iconName: "train.side.front.car",
                    text: card.line,
                    tintColor: Theme.Colors.accentText
                )

                if let platform = card.platform, !platform.isEmpty {
                    GlassPillView(
                        iconName: "signpost.right.fill",
                        text: "Gleis \(platform)",
                        tintColor: Color(red: 190/255, green: 140/255, blue: 255/255)
                    )
                }

                Spacer()

                if let delay = card.delayMin {
                    if delay == 0 {
                        GlassPillView(
                            iconName: "checkmark.circle.fill",
                            text: "Pünktlich",
                            tintColor: Theme.Colors.successText
                        )
                    } else {
                        GlassPillView(
                            iconName: "exclamationmark.circle.fill",
                            text: "+\(delay) Min.",
                            tintColor: Theme.Colors.dangerText
                        )
                    }
                }
            }

            // Hero Departure Time (48pt+) as the primary visual focus
            VStack(alignment: .leading, spacing: 4) {
                HStack(alignment: .firstTextBaseline, spacing: 12) {
                    Text(CardFormatters.formatTime(card.departure))
                        .font(Theme.Typography.heroDeparture)
                        .foregroundColor(Theme.Colors.textPrimary)
                        .shadow(color: Color.black.opacity(0.3), radius: 6, x: 0, y: 2)

                    VStack(alignment: .leading, spacing: 2) {
                        Text("Abfahrt")
                            .font(Theme.Typography.caption)
                            .foregroundColor(Theme.Colors.textMuted)
                            .textCase(.uppercase)

                        Text(card.from)
                            .font(Theme.Typography.station)
                            .foregroundColor(Theme.Colors.textPrimary)
                            .lineLimit(1)
                    }
                }
            }
            .padding(.vertical, 2)

            // Journey Route: From -> To with arrival and duration
            HStack(alignment: .center, spacing: 12) {
                VStack(alignment: .leading, spacing: 4) {
                    Text("Ankunft: \(CardFormatters.formatTime(card.arrival))")
                        .font(Theme.Typography.timeLarge)
                        .foregroundColor(Theme.Colors.textPrimary)

                    Text(card.to)
                        .font(Theme.Typography.station)
                        .foregroundColor(Theme.Colors.textSecondary)
                }

                Spacer()

                VStack(alignment: .trailing, spacing: 4) {
                    HStack(spacing: 6) {
                        Image(systemName: "clock")
                            .font(.system(size: 17, weight: .semibold))
                        Text(CardFormatters.formatDuration(from: card.departure, to: card.arrival))
                            .font(Theme.Typography.headline)
                    }
                    .foregroundColor(Theme.Colors.accentText)

                    Text(card.transfers == 0 ? "Direktverbindung" : "\(card.transfers) Umstieg(e)")
                        .font(Theme.Typography.caption)
                        .foregroundColor(Theme.Colors.textMuted)
                }
            }
            .padding(16)
            .background {
