    public init(card: FlightCard, onAction: ((String) -> Void)? = nil) {
        self.card = card
        self.onAction = onAction
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 20) {
            // Header pills: Flight number, Booking reference
