            HStack(alignment: .firstTextBaseline) {
                // Departure
                VStack(alignment: .leading, spacing: 4) {
                    Text(CardFormatters.formatTime(card.departure))
                        .font(Theme.Typography.timeLarge)
                        .foregroundColor(Theme.Colors.textPrimary)

                    Text(card.from)
                        .font(.system(size: 32, weight: .heavy, design: .rounded))
                        .foregroundColor(Theme.Colors.textPrimary)

                    Text(CardFormatters.formatShortDate(card.departure))
                        .font(Theme.Typography.caption)
                        .foregroundColor(Theme.Colors.textSecondary)
                }

                Spacer()

                // Airplane Flight Track
                VStack(spacing: 6) {
                    HStack(spacing: 4) {
                        Circle()
                            .fill(Theme.Colors.accentText)
                            .frame(width: 6, height: 6)

                        Rectangle()
                            .fill(
                                LinearGradient(
                                    colors: [Theme.Colors.accentText, Theme.Colors.accentText.opacity(0.3)],
                                    startPoint: .leading,
                                    endPoint: .trailing
