                            )
                            .frame(height: 2)

                        Image(systemName: "airplane")
                            .font(.system(size: 20, weight: .bold))
                            .foregroundColor(Theme.Colors.accentText)

                        Rectangle()
                            .fill(
                                LinearGradient(
                                    colors: [Theme.Colors.accentText.opacity(0.3), Theme.Colors.accentText],
